function demoMain(idx,label){
  var mods=[["ui",["util","api"],"app"],["db",["util"],"app,srv"],["util",[],"ui,db"],["api",["db"],"ui"]];
  var m=mods[idx%mods.length]; var out=m[1].length, inn=m[2].split(",").length;
  var instability=out/(out+inn); var verdict=instability>0.6?"UNSTABLE (too many outgoing deps)":instability<0.3?"STABLE":"BALANCED";
  return "["+label+"] module '"+m[0]+"': efferent="+out+" afferent="+inn+" instability="+instability.toFixed(2)+" => "+verdict;
}

